"""Restore unambiguous ligature text in PDFs generated by the Story backend."""

from __future__ import annotations

from io import BytesIO
from typing import Any

from opendoc_model import ConversionReport, IssueSeverity


def restore_ligature_unicode(pdf: Any, report: ConversionReport, location: str) -> None:
    """Keep glyphs and shaping; amend only generated Identity-H Unicode maps.

    GSUB ligatures without a cmap entry can be omitted by the backend's ToUnicode
    generator. Only a unique sequence of uniquely encoded component glyphs is
    evidence of the missing text. Other fonts and ambiguous substitutions retain
    the subsequent text verifier's refusal behavior.
    """
    try:
        from fontTools.ttLib import TTFont
    except ImportError:
        return
    fonts = {int(font[0]) for page in pdf for font in page.get_fonts(full=True) if int(font[0]) > 0}
    if len(fonts) > 200:
        report.add(IssueSeverity.ERROR, 'pdf-unicode-limit', 'Generated font inventory exceeds the Unicode profile', location)
        return
    repaired = 0
    work = 0
    for xref in sorted(fonts):
        if pdf.xref_get_key(xref, 'Encoding') != ('name', '/Identity-H'):
            continue
        kind, reference = pdf.xref_get_key(xref, 'ToUnicode')
        if kind != 'xref':
            continue
        descendants = pdf.xref_get_key(xref, 'DescendantFonts')[1].strip('[] ').split()
        if len(descendants) != 3 or descendants[1:] != ['0', 'R']:
            continue
        descendant = int(descendants[0])
        if pdf.xref_get_key(descendant, 'Subtype') != ('name', '/CIDFontType2'):
            continue
        if pdf.xref_get_key(descendant, 'CIDToGIDMap') not in (('null', 'null'), ('name', '/Identity')):
            continue
        data = pdf.extract_font(xref)[3]
        work += len(data)
        if len(data) > 20_000_000 or work > 50_000_000:
            report.add(IssueSeverity.ERROR, 'pdf-unicode-limit', 'Embedded fonts exceed the Unicode profile', location)
            return
        try:
            with TTFont(BytesIO(data), lazy=False) as font:
                mapping = _ligature_map(font)
        except Exception:  # noqa: BLE001 - unknown font data is not evidence for a repair
            continue
        if not mapping:
            continue
        unicode_xref = int(reference.split()[0])
        stream = pdf.xref_stream(unicode_xref)
        if len(stream) > 2_000_000 or stream.count(b'endcmap') != 1:
            continue
        chunks = []
        items = sorted(mapping.items())
        for start in range(0, len(items), 100):
            group = items[start:start + 100]
            chunks.append(f'{len(group)} beginbfchar\n' + '\n'.join(
                f'<{gid:04x}> <{text.encode("utf-16-be").hex()}>' for gid, text in group
            ) + '\nendbfchar\n')
        pdf.update_stream(unicode_xref, stream.replace(b'endcmap', ''.join(chunks).encode('ascii') + b'endcmap'))
        repaired += len(mapping)
    report.metrics['pdf_ligature_unicode_mappings'] = report.metrics.get('pdf_ligature_unicode_mappings', 0) + repaired


def _ligature_map(font: Any) -> dict[int, str]:
    if 'GSUB' not in font:
        return {}
    encoded: dict[str, set[str]] = {}
    for code, glyph in (font.getBestCmap() or {}).items():
        if 0 <= code <= 0x10ffff and not 0xd800 <= code <= 0xdfff:
            encoded.setdefault(glyph, set()).add(chr(code))
    candidates: dict[str, set[str]] = {}
    uncertain: set[str] = set()
    lookups = font['GSUB'].table.LookupList
    if lookups is None or len(lookups.Lookup) > 1000:
        return {}
    count = 0
    for lookup in lookups.Lookup:
        for table in lookup.SubTable:
            if lookup.LookupType == 7:
                if table.ExtensionLookupType != 4:
                    continue
                table = table.ExtSubTable
            elif lookup.LookupType != 4:
                continue
            for first, ligatures in table.ligatures.items():
                for ligature in ligatures:
                    count += 1
                    if count > 100_000:
                        return {}
                    components = [first, *ligature.Component]
                    if len(components) > 32 or not all(len(encoded.get(glyph, ())) == 1 for glyph in components):
                        uncertain.add(ligature.LigGlyph)
                        continue
                    text = ''.join(next(iter(encoded[glyph])) for glyph in components)
                    candidates.setdefault(ligature.LigGlyph, set()).add(text)
    return {font.getGlyphID(glyph): next(iter(texts)) for glyph, texts in candidates.items()
            if glyph not in encoded and glyph not in uncertain and len(texts) == 1 and font.getGlyphID(glyph) <= 0xffff}
